interface CustomerReader {
    Customer findById(long id);
}

interface CustomerWriter {
    void save(Customer customer);
}

final class ReadOnlyCustomers implements CustomerReader {
    @Override
    public Customer findById(long id) {
        // read from a replica
        return null;
    }
}

// A caller that requires saving asks for CustomerWriter.
// ReadOnlyCustomers never claims to provide that capability.
```

