interface PaymentService {
    // Contract: returns transaction ID, throws PaymentException on failure
    // Postcondition: order status is updated to PAID or FAILED
    String processPayment(Long orderId, BigDecimal amount);
}

@Service
class StripePaymentService implements PaymentService {
    @Override
    public String processPayment(Long orderId, BigDecimal amount) {
        var transactionId = stripeApi.charge(amount);  // Call Stripe
        orderRepo.updateStatus(orderId, OrderStatus.PAID);  // Honors contract
        return transactionId;
    }
}

// Contract violation: returns null, doesn't update order
@Service
class MockPaymentService implements PaymentService {
    @Override
    public String processPayment(Long orderId, BigDecimal amount) {
        return null;  // Violates postcondition: must return transaction ID
        // Missing: order status update
    }
}

```java
// IS-A by name, but does NOT behave-like-a -> LSP violation
class Bird {
    void fly() { /* moves through the air */ }
}
class Penguin extends Bird {            // Penguin IS-A Bird (structurally)
    @Override void fly() {
        throw new UnsupportedOperationException("penguins can't fly"); // breaks callers
    }
}

void migrate(Bird b) { b.fly(); }       // expects every Bird to fly
// migrate(new Penguin()) crashes at runtime: behaves-like-a failed

// Fix: model on behavior, not just the noun
interface Flyer { void fly(); }
class Sparrow implements Flyer { public void fly() { /* ok */ } }
// Penguin simply does not implement Flyer -> the compiler prevents misuse
```
IS-A is structural; behaves-like-a is the real substitution test that LSP enforces.
